<?php endif;?>
<script>
(()=>{const modal=document.getElementById('family-modal');if(!modal)return;const form=document.getElementById('family-edit-form'),items=JSON.parse(document.getElementById('family-items-json').textContent),byId=id=>items.find(x=>x.id===Number(id)),image=document.getElementById('family-image-preview');let url=null;
function open(item){form.reset();document.getElementById('family-id').value=item?.id||0;document.getElementById('family-title').value=item?.titulo||'';document.getElementById('family-url').value=item?.url||'';document.getElementById('family-order').value=item?.orden||items.length+1;document.getElementById('family-visible').value=item?.visible||'si';const ta=document.getElementById('family-description');ta.value=item?.descripcion||'';ta.dispatchEvent(new Event('input',{bubbles:true}));document.getElementById('family-modal-title').textContent=item?'Editar contenido':'Agregar contenido';image.hidden=!item?.imagen;if(item?.imagen)image.src=item.imagen;modal.hidden=false;document.body.style.overflow='hidden';}
function close(){modal.hidden=true;document.body.style.overflow='';}
document.getElementById('family-add').addEventListener('click',()=>open(null));document.querySelectorAll('[data-family-edit]').forEach(b=>b.addEventListener('click',()=>open(byId(b.dataset.familyEdit))));document.querySelectorAll('[data-family-close]').forEach(b=>b.addEventListener('click',close));document.querySelectorAll('[data-family-view]').forEach(b=>b.addEventListener('click',()=>{const cards=b.dataset.familyView==='cards';document.getElementById('family-list').hidden=cards;document.getElementById('family-cards').hidden=!cards;document.querySelectorAll('[data-family-view]').forEach(x=>x.classList.toggle('active',x===b));}));
document.querySelectorAll('[data-family-preview]').forEach(b=>b.addEventListener('click',()=>{const i=byId(b.dataset.familyPreview);if(i)open(i)}));
document.getElementById('family-image').addEventListener('change',e=>{if(url)URL.revokeObjectURL(url);const f=e.target.files[0];if(!f)return;if(!['image/jpeg','image/png','image/webp'].includes(f.type)||f.size>5242880){alert('Imagen inválida o mayor a 5 MB');e.target.value='';return;}url=URL.createObjectURL(f);image.src=url;image.hidden=false;});
const tbody=document.getElementById('family-sortable');let dragged=null;tbody.querySelectorAll('.family-tr').forEach(tr=>{tr.addEventListener('dragstart',e=>{dragged=tr;tr.classList.add('dragging');e.dataTransfer.effectAllowed='move'});tr.addEventListener('dragover',e=>{e.preventDefault();if(!dragged||dragged===tr)return;tr.classList.add('dragover');const r=tr.getBoundingClientRect();tbody.insertBefore(dragged,e.clientY<r.top+r.height/2?tr:tr.nextSibling)});tr.addEventListener('dragleave',()=>tr.classList.remove('dragover'));tr.addEventListener('dragend',()=>{tbody.querySelectorAll('.family-tr').forEach(x=>x.classList.remove('dragging','dragover'));document.getElementById('family-save-order').hidden=false;dragged=null})});document.getElementById('family-save-order').addEventListener('click',()=>{document.getElementById('family-order-ids').value=[...tbody.querySelectorAll('.family-tr')].map(x=>x.dataset.id).join(',');document.getElementById('family-order-form').submit()});
})();
</script>
